<script setup lang="ts">
import {computed,ref,onMounted} from 'vue';import {useWorkbench} from '../stores/workbench';import {fmt,percent} from '../api/client';
const s=useWorkbench(),feedback=ref('negotiate'),selected=ref<string[]>([]),period=ref(1);
const m=computed(()=>s.metrics||{}),before=computed(()=>m.value.before||{}),after=computed(()=>(m.value.after?.periods||[]).find((x:any)=>x.period===period.value)||m.value.after||{}),n1=computed(()=>m.value.n1||{});
const cards=computed(()=>[{name:'最大线路负载率',before:percent(before.value.loading?.max),after:percent(after.value.loading?.max),detail:'平均 '+percent(before.value.loading?.mean)+' · 重载 '+(before.value.loading?.heavy_count??'—')+' 条'},{name:'最大电压偏移',before:fmt(before.value.voltage?.max,4)+' p.u.',after:after.value.voltage?fmt(after.value.voltage.max,4)+' p.u.':'—',detail:(before.value.voltage?.violations??'—')+' 个母线越限'},{name:'N−1 直流筛查',before:percent(n1.value.pass_rate),after:percent(after.value.n1?.pass_rate),detail:(n1.value.passed??'—')+' / '+(n1.value.evaluated??'—')+' 个事故'}]);
onMounted(()=>{if(!s.metrics)s.evaluate().catch(()=>{})});
const source=computed(()=>/本地|模拟|local|mock/i.test(m.value.risk?.source||'本地')?'本地模拟':'课题 3 服务');
</script>
<template><div class="content-pad"><div class="panel-heading"><div><div class="eyebrow">M7 / 指标评估与协商</div><h2>运行风险与反馈</h2></div><span class="risk-context-pill">{{m.evaluation_stage==='post_result'?'方案评估':'求解前 · 基态评估'}}</span><el-button :loading="s.busy" @click="s.evaluate().catch(()=>{})">重新评估</el-button></div>
 <template v-if="s.metrics"><div v-if="m.after?.periods?.length" class="toolbar"><span>调整后时段</span><el-select v-model="period" style="width:140px"><el-option v-for="p in m.after.periods" :key="p.period" :value="p.period" :label="'第'+p.period+'时段'"/></el-select></div>
 <div class="risk-metric-grid"><div v-for="card in cards" :key="card.name" class="metric-card"><span>{{card.name}}</span><div class="metric-values"><div><small>调整前</small><strong>{{card.before}}</strong></div><div><small>调整后</small><strong>{{card.after}}</strong></div></div><p>{{card.detail}}</p></div></div>
 <div class="v4-actions"><span class="status-chip">PTDF / LODF 直流筛查</span><span class="status-chip" v-if="n1.islanding_count">孤岛事故 {{n1.islanding_count}} 项 · 单独统计</span></div>
 <div class="two-columns"><div class="metric-unavailable"><strong>静态电压稳定裕度</strong><span class="status-chip">待接入连续潮流</span></div><div class="metric-unavailable"><strong>新能源消纳率</strong><span class="status-chip">缺少新能源数据</span></div></div>
 <section class="risk-assessment"><div class="section-heading"><h3>课题 3 风险评估</h3><span class="status-chip">{{source}}</span></div><div class="risk-heading"><div class="risk-level" :class="{'高':'high','中':'medium','低':'low'}[m.risk?.risk_level as string]">{{m.risk?.risk_level||'—'}}<small>风险等级</small></div><div><strong>{{m.risk?.basis||'当前断面'}}</strong><ul class="risk-reasons"><li v-for="(reason,i) in m.risk?.reasons||[]" :key="i">{{reason}}</li></ul></div></div></section>
 <section class="spec-section"><div class="section-heading"><h3>反馈方式</h3><el-radio-group v-model="feedback" size="small"><el-radio-button value="negotiate">协商调整</el-radio-button><el-radio-button value="reward">Reward</el-radio-button></el-radio-group></div>
  <template v-if="feedback==='negotiate'"><p class="muted">选择调整建议，返回模型页补全并确认。</p><div v-for="sug in m.suggestions||[]" :key="sug.id" class="suggestion-card"><el-checkbox v-model="selected" :value="sug.id"><strong>{{sug.title}}</strong></el-checkbox><p>{{sug.reason}}</p></div><div class="panel-bottom-actions"><el-button @click="s.step=3;s.tab='spec'">返回模型</el-button><el-button type="primary" :disabled="!selected.length||!s.confirmed" :loading="s.busy" @click="s.adjust(selected).catch(()=>{})" data-testid="apply-adjustment">采纳建议并创建新版本</el-button></div><p v-if="!s.confirmed" class="small-note">请先确认当前模型，再生成协商版本。</p></template>
  <div v-else class="soft-panel panel-pad"><div class="section-heading"><h3>风险等级 → 奖励项</h3><span class="status-chip">接口预留</span></div><div class="static-field">{{m.risk?.reward??'待接入'}}</div><p>风险惩罚、安全约束与优化目标共同组成后续强化学习的反馈。</p><details><summary>Reward 数据格式</summary><pre class="json-block">{{JSON.stringify(s.integrations.find(i=>i.id==='reward')?.request,null,2)}}</pre></details><RouterLink to="/decomposition">查看 CMDP 与强化学习入口 ↗</RouterLink></div>
 </section></template><div v-else class="inline-empty large">正在计算指标…</div>
</div></template>
